const opType = msg.operationType || 'read';

if (opType === 'write') {
    return [null, msg];
} else {
    return [msg, null];
}

flow.set("bchg_rpc_response_topic", msg.rpcResponseTopic);
flow.set("bchg_write_result", msg.writeResult || null);

flow.set("bchg_part_gen_timing", null);
flow.set("bchg_part_gen_charge", null);
flow.set("bchg_part_grid", null);

return msg;

msg.baseAddr = 221;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 221,
    quantity: 2
};
return msg;

msg.baseAddr = 224;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 224,
    quantity: 2
};
return msg;

msg.baseAddr = 227;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 227,
    quantity: 4
};
return msg;

let raw = msg.payload;
let data = raw;
if (data && Array.isArray(data.data)) {
    data = data.data;
}

if (typeof raw === "string" || !Array.isArray(data)) {
    return null;
}

let baseAddr = msg.baseAddr;
if (typeof baseAddr !== "number") {
    baseAddr = (msg.modbusRequest && msg.modbusRequest.address);
}
if (typeof baseAddr !== "number") {
    return null;
}

if (baseAddr === 221) {
    flow.set("bchg_part_gen_timing", {
        maxRunTimeHours: Math.round((data[0] || 0) * 0.1 * 10) / 10,
        coolingTimeHours: Math.round((data[1] || 0) * 0.1 * 10) / 10
    });
}
else if (baseAddr === 224) {
    flow.set("bchg_part_gen_charge", {
        startSocPercent: data[0] || 0,
        chargeCurrentA: data[1] || 0
    });
}
else if (baseAddr === 227) {
    flow.set("bchg_part_grid", {
        gridStartSocPercent: data[0] || 0,
        gridChargeCurrentA: data[1] || 0,
        genEnabled: (data[2] || 0) === 1,
        gridEnabled: (data[3] || 0) === 1
    });
}
else {
    return null;
}

const genTimingPart = flow.get("bchg_part_gen_timing");
const genChargePart = flow.get("bchg_part_gen_charge");
const gridPart = flow.get("bchg_part_grid");

if (!genTimingPart || !genChargePart || !gridPart) {
    return null;
}

const gatewayId = global.get("GATEWAY_ID") || env.get("GATEWAY_ID") || "EC100-GW-001";
const inverterSN = global.get("INVERTER_SN") || env.get("INVERTER_SN") || "Unknown";

const state = {
    kind: "BatteryChargeSourceConfigState",
    timestampUtc: new Date().toISOString(),
    gatewayId: gatewayId,
    inverterSerialNumber: inverterSN,

    generator: {
        enabled: gridPart.genEnabled,
        startSocPercent: genChargePart.startSocPercent,
        chargeCurrentA: genChargePart.chargeCurrentA,
        maxRunTimeHours: genTimingPart.maxRunTimeHours,
        coolingTimeHours: genTimingPart.coolingTimeHours
    },

    grid: {
        enabled: gridPart.gridEnabled,
        startSocPercent: gridPart.gridStartSocPercent,
        chargeCurrentA: gridPart.gridChargeCurrentA
    }
};

flow.set("bchg_part_gen_timing", null);
flow.set("bchg_part_gen_charge", null);
flow.set("bchg_part_grid", null);

const writeResult = flow.get("bchg_write_result");
const rpcResponseTopic = flow.get("bchg_rpc_response_topic");

flow.set("bchg_write_result", null);
flow.set("bchg_rpc_response_topic", null);

if (writeResult) {
    msg.payload = {
        success: writeResult.success,
        message: writeResult.message,
        writes: writeResult.writes,
        state: state
    };
} else {
    msg.payload = state;
}

msg.state = state;
msg.rpcResponseTopic = rpcResponseTopic;

return msg;

if (!msg.rpcResponseTopic) {
    return null;
}

msg.topic = msg.rpcResponseTopic;
return msg;

// Parse RPC params and build write queue
const params = msg.rpcParams || {};
const gen = params.generator || {};
const grid = params.grid || {};

const writes = [];

// Generator settings (221,222 are read-only)
if (gen.startSocPercent !== undefined) {
    writes.push({ register: 224, value: gen.startSocPercent, name: "Gen Start SOC" });
}
if (gen.chargeCurrentA !== undefined) {
    writes.push({ register: 225, value: gen.chargeCurrentA, name: "Gen Charge Current" });
}

// Grid settings
if (grid.startSocPercent !== undefined) {
    writes.push({ register: 227, value: grid.startSocPercent, name: "Grid Start SOC" });
}
if (grid.chargeCurrentA !== undefined) {
    writes.push({ register: 228, value: grid.chargeCurrentA, name: "Grid Charge Current" });
}

// Enable flags
if (gen.enabled !== undefined) {
    writes.push({ register: 229, value: gen.enabled ? 1 : 0, name: "Gen Charge Enable" });
}
if (grid.enabled !== undefined) {
    writes.push({ register: 230, value: grid.enabled ? 1 : 0, name: "Grid Charge Enable" });
}

if (writes.length === 0) {
    msg.operationType = 'read';
    return [null, msg];
}

// Store to GLOBAL context
global.set("bchg_write_queue", writes);
global.set("bchg_write_index", 0);
global.set("bchg_write_results", []);
global.set("bchg_write_rpc_topic", msg.rpcResponseTopic);

node.status({ fill: "blue", shape: "dot", text: `${writes.length} writes queued` });

return [msg, null];

const writes = global.get("bchg_write_queue") || [];
const index = global.get("bchg_write_index") || 0;

if (index >= writes.length) {
    return null;
}

const current = writes[index];

const newMsg = {
    payload: {
        fc: 16,
        unitid: 1,
        address: current.register,
        quantity: 1,
        value: [current.value]
    },
    currentWrite: current,
    writeIndex: index
};

node.status({ fill: "blue", shape: "dot", text: `[${index+1}/${writes.length}] ${current.name}` });

return newMsg;

const writes = global.get("bchg_write_queue") || [];
let index = global.get("bchg_write_index") || 0;
const results = global.get("bchg_write_results") || [];

// Record success
const current = writes[index];
if (current) {
    results.push({ 
        register: current.register, 
        name: current.name, 
        value: current.value, 
        success: true 
    });
    global.set("bchg_write_results", results);
}

// Move to next
index++;
global.set("bchg_write_index", index);

node.status({ fill: "green", shape: "dot", text: `${current.name} OK` });

// More writes?
if (index < writes.length) {
    return [{ doNext: true }, null];
}

// All done - go to read
const rpcTopic = global.get("bchg_write_rpc_topic");

global.set("bchg_write_queue", null);
global.set("bchg_write_index", null);
global.set("bchg_write_rpc_topic", null);

const finalMsg = {
    writeResult: {
        success: true,
        message: `Successfully wrote ${results.length} register(s)`,
        writes: results
    },
    rpcResponseTopic: rpcTopic
};

node.status({ fill: "green", shape: "dot", text: `All ${results.length} writes OK!` });

return [null, finalMsg];
